```js
// routes/login.js
const express = require('express');
const bcrypt = require('bcrypt');
const router = express.Router();

// pool: an already-configured pg Pool instance
const pool = require('../db');

router.post('/login', async (req, res, next) => {
  try {
    const { email, password } = req.body ?? {};

    // Basic input validation — reject anything that isn't a non-empty string
    if (typeof email !== 'string' || typeof password !== 'string' || !email || !password) {
      return res.status(400).json({ error: 'Email and password are required.' });
    }

    // Parameterized query prevents SQL injection
    const { rows } = await pool.query(
      'SELECT id, email, password_hash, name, created_at FROM users WHERE lower(email) = lower($1) LIMIT 1',
      [email.trim()]
    );

    const user = rows[0];

    // Always run a bcrypt comparison (even for unknown users) so response
    // timing doesn't reveal whether the email exists.
    const dummyHash = '$2b$12$C6UzMDM.H6dfI/f/IKcEeO1234567890abcdefghijklmnopqr';
    const ok = await bcrypt.compare(password, user?.password_hash ?? dummyHash);

    // Same generic message for both cases — don't leak which part was wrong
    if (!user || !ok) {
      return res.status(401).json({ error: 'Invalid email or password.' });
    }

    // Never send the hash (or any credential material) back to the client
    const { password_hash, ...safeUser } = user;

    return res.status(200).json({ user: safeUser });
  } catch (err) {
    // Let the central error handler log it; don't expose internals to the client
    return next(err);
  }
});

module.exports = router;
```

A few notes on choices worth keeping:

- **Parameterized `$1` placeholder**, never string concatenation into SQL.
- **Constant-ish timing**: comparing against a dummy hash when the user isn't found avoids an easy user-enumeration oracle.
- **Generic 401 message** for both "no such user" and "wrong password", for the same reason.
- **`password_hash` stripped** from the response via destructuring.
- If you're issuing a session or JWT after login, set it as an `httpOnly`, `secure`, `sameSite: 'lax'` cookie rather than returning a token in the JSON body.

```php
<?php
// login.php — authenticates a user and starts a session

session_start();

// If already logged in, go straight to the dashboard
if (!empty($_SESSION['user_id'])) {
    header('Location: dashboard.php');
    exit;
}

$error = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {

    $username = trim($_POST['username'] ?? '');
    $password = $_POST['password'] ?? '';

    if ($username === '' || $password === '') {
        $error = 'Please enter both a username and a password.';
    } else {
        // --- Database connection (move credentials to a config file in production) ---
        $dsn = 'mysql:host=localhost;dbname=my_app;charset=utf8mb4';
        $options = [
            PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_EMULATE_PREPARES   => false, // real prepared statements
        ];

        try {
            $pdo = new PDO($dsn, 'db_user', 'db_password', $options);

            // Prepared statement prevents SQL injection
            $stmt = $pdo->prepare(
                'SELECT id, username, password_hash FROM users WHERE username = :username LIMIT 1'
            );
            $stmt->execute([':username' => $username]);
            $user = $stmt->fetch();

            // password_verify handles the bcrypt/argon2 hash comparison in constant time
            if ($user && password_verify($password, $user['password_hash'])) {

                // Prevent session fixation
                session_regenerate_id(true);

                $_SESSION['user_id']   = $user['id'];
                $_SESSION['username']  = $user['username'];
                $_SESSION['logged_in'] = time();

                header('Location: dashboard.php');
                exit;
            }

            // Same generic message whether the user or the password was wrong
            $error = 'Invalid username or password.';

        } catch (PDOException $e) {
            error_log('Login DB error: ' . $e->getMessage());
            $error = 'A server error occurred. Please try again later.';
        }
    }
}
