```js
// api-keys.js
const crypto = require('crypto');
const { Pool } = require('pg');

const pool = new Pool(); // configure via PG* env vars

/*
Expected table:

CREATE TABLE api_keys (
  id           bigserial PRIMARY KEY,
  customer_id  bigint NOT NULL,
  prefix       text NOT NULL UNIQUE,      -- public lookup handle
  key_hash     bytea NOT NULL,            -- SHA-256 of the full secret
  created_at   timestamptz NOT NULL DEFAULT now(),
  last_used_at timestamptz,
  expires_at   timestamptz,
  revoked_at   timestamptz
);
CREATE INDEX ON api_keys (customer_id);
*/

const PREFIX_BYTES = 6;   // ~8 chars, identifies the row
const SECRET_BYTES = 32;  // 256 bits of entropy — the actual secret

// base64url without padding
const b64u = (buf) => buf.toString('base64url');

const sha256 = (str) => crypto.createHash('sha256').update(str, 'utf8').digest();

/**
 * Generate a new API key for a customer.
 * Only the returned `apiKey` string is ever shown — it is not recoverable later.
 *
 * @returns {Promise<{id: string, prefix: string, apiKey: string, createdAt: Date}>}
 */
async function generateApiKey(customerId, { expiresAt = null, client = pool } = {}) {
  const prefix = b64u(crypto.randomBytes(PREFIX_BYTES));
  const secret = b64u(crypto.randomBytes(SECRET_BYTES));

  // Presented format: sk_<prefix>_<secret>
  const apiKey = `sk_${prefix}_${secret}`;
  const keyHash = sha256(secret);

  const { rows } = await client.query(
    `INSERT INTO api_keys (customer_id, prefix, key_hash, expires_at)
     VALUES ($1, $2, $3, $4)
     RETURNING id, prefix, created_at`,
    [customerId, prefix, keyHash, expiresAt]
  );

  return {
    id: rows[0].id,
    prefix: rows[0].prefix,
    createdAt: rows[0].created_at,
    apiKey, // show once, then discard
  };
}

/** Parse "sk_<prefix>_<secret>" -> { prefix, secret } or null. */
function parseApiKey(presented) {
  if (typeof presented !== 'string') return null;
  const parts = presented.split('_');
  if (parts.length !== 3 || parts[0] !== 'sk' || !parts[1] || !parts[2]) return null;
  return { prefix: parts[1], secret: parts[2] };
}

/**
 * Verify a presented API key.
 * @returns {Promise<{valid: boolean, customerId?: string, keyId?: string, reason?: string}>}
 */
async function verifyApiKey(presented, { client = pool, touch = true } = {}) {
  const parsed = parseApiKey(presented);
  if (!parsed) return { valid: false, reason: 'malformed' };

  const { rows } = await client.query(
    `SELECT id, customer_id, key_hash, expires_at, revoked_at
     FROM api_keys WHERE prefix = $1`,
    [parsed.prefix]
  );

  const row = rows[0];
  // Compare against a dummy hash when not found to keep timing uniform.
  const stored = row ? row.key_hash : Buffer.alloc(32);
  const candidate = sha256(parsed.secret);
  const match = crypto.timingSafeEqual(candidate, stored);

  if (!row || !match) return { valid: false, reason: 'not_found' };
  if (row.revoked_at) return { valid: false, reason: 'revoked' };
  if (row.expires_at && row.expires_at <= new Date()) return { valid: false, reason: 'expired' };

  if (touch) {
    // fire-and-forget usage timestamp
    client
      .query(`UPDATE api_keys SET last_used_at = now() WHERE id = $1`, [row.id])
      .catch(() => {});
  }

  return { valid: true, customerId: row.customer_id, keyId: row.id };
}

/** Revoke a key by its public prefix. */
async function revokeApiKey(prefix, { client = pool } = {}) {
  const { rowCount } = await client.query(
    `UPDATE api_keys SET revoked_at = now()
     WHERE prefix = $1 AND revoked_at IS NULL`,
    [prefix]
  );
  return rowCount > 0;
}

module.exports = { generateApiKey, verifyApiKey, revokeApiKey, pool };
