<?php
/**
 * Fetch a page of products for a listing page.
 *
 * Reads: ?page=1&sort=price_asc&q=search+term
 *
 * @param mysqli $db       Open mysqli connection.
 * @param int    $perPage  Rows per page.
 * @return array{rows: array<int,array<string,mixed>>, page:int, perPage:int, total:int, pages:int}
 */
function getProductListing(mysqli $db, int $perPage = 20): array
{
    // --- Page number: force to a sane positive integer ---
    $page = filter_input(INPUT_GET, 'page', FILTER_VALIDATE_INT, [
        'options' => ['default' => 1, 'min_range' => 1, 'max_range' => 100000],
    ]);
    $perPage = max(1, min($perPage, 100));           // clamp to avoid huge result sets
    $offset  = ($page - 1) * $perPage;

    // --- Sorting: NEVER interpolate user input into SQL. Whitelist only. ---
    $sortMap = [
        'newest'     => 'p.created_at DESC',
        'oldest'     => 'p.created_at ASC',
        'price_asc'  => 'p.price ASC',
        'price_desc' => 'p.price DESC',
        'name_asc'   => 'p.name ASC',
        'name_desc'  => 'p.name DESC',
    ];
    $sortKey  = (string)($_GET['sort'] ?? 'newest');
    $orderBy  = $sortMap[$sortKey] ?? $sortMap['newest'];
    $orderBy .= ', p.id DESC'; // deterministic tie-breaker for stable pagination

    // --- Search term: optional, trimmed, length-capped ---
    $term = trim((string)($_GET['q'] ?? ''));
    $term = mb_substr($term, 0, 100);

    $where  = 'p.is_active = 1';
    $params = [];
    $types  = '';

    if ($term !== '') {
        // Escape LIKE wildcards so users can't turn a search into a full scan pattern.
        $like = '%' . str_replace(['\\', '%', '_'], ['\\\\', '\%', '\_'], $term) . '%';
        $where .= ' AND (p.name LIKE ? OR p.sku LIKE ?)';
        $types .= 'ss';
        $params[] = $like;
        $params[] = $like;
    }

    // --- Total count (for pager) ---
    $countSql = "SELECT COUNT(*) FROM products p WHERE {$where}";
    $stmt = $db->prepare($countSql);
    if ($types !== '') {
        $stmt->bind_param($types, ...$params);
    }
    $stmt->execute();
    $stmt->bind_result($total);
    $stmt->fetch();
    $stmt->close();
    $total = (int)$total;

    // --- Page of rows ---
    $sql = "SELECT p.id, p.sku, p.name, p.price, p.image_url, p.created_at
            FROM products p
            WHERE {$where}
            ORDER BY {$orderBy}
            LIMIT ? OFFSET ?";

    $stmt = $db->prepare($sql);
    $rowParams = $params;
    $rowParams[] = $perPage;
    $rowParams[] = $offset;
    $stmt->bind_param($types . 'ii', ...$rowParams);
    $stmt->execute();

    $rows = $stmt->get_result()->fetch_all(MYSQLI_ASSOC);
    $stmt->close();

    return [
        'rows'    => $rows,
        'page'    => $page,
        'perPage' => $perPage,
        'total'   => $total,
        'pages'   => (int)ceil($total / $perPage),
    ];
}
```

Notes:
- Enable exception-based error reporting once at bootstrap so failed prepares don't silently return bad data: `mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);`
- Set the connection charset to `utf8mb4` (`$db->set_charset('utf8mb4')`) — required for `bind_param` escaping guarantees and correct multibyte handling.
- Escape all returned values with `htmlspecialchars()` at render time; this function returns raw DB data.

```js
// Fetch orders for a user, optionally filtered by status and start date.
// Uses parameterized queries to avoid SQL injection.
async function getUserOrders(userId, status, fromDate) {
  let sql = `
    SELECT id, user_id, status, total, created_at
    FROM orders
    WHERE user_id = ?
  `;
  const params = [userId];

  // Only append optional filters when a value was actually supplied.
  if (status !== undefined && status !== null && status !== '') {
    sql += ' AND status = ?';
    params.push(status);
  }

  if (fromDate !== undefined && fromDate !== null && fromDate !== '') {
    sql += ' AND created_at >= ?';
    params.push(fromDate instanceof Date ? fromDate : new Date(fromDate));
  }

  sql += ' ORDER BY created_at DESC';

  // pool.execute uses prepared statements; rows is the result set.
  const [rows] = await pool.execute(sql, params);
  return rows;
}

module.exports = { getUserOrders };
