'use strict';

const { execFile } = require('child_process');
const path = require('path');
const fs = require('fs');

// Only allow files inside these directories (adjust to your app's layout).
const UPLOAD_DIR = path.resolve(__dirname, 'uploads');
const THUMB_DIR = path.resolve(__dirname, 'thumbnails');

/**
 * Resolve a user-supplied path and ensure it stays inside `baseDir`.
 * Blocks "../" traversal and absolute paths pointing elsewhere.
 */
function safeResolve(baseDir, userPath) {
  if (typeof userPath !== 'string' || userPath.length === 0) {
    throw new Error('Invalid path');
  }
  // Reject NUL bytes, which can truncate paths in some native layers.
  if (userPath.includes('\0')) throw new Error('Invalid path');

  const resolved = path.resolve(baseDir, userPath);
  if (resolved !== baseDir && !resolved.startsWith(baseDir + path.sep)) {
    throw new Error('Path escapes allowed directory');
  }
  return resolved;
}

/**
 * Create a thumbnail with ImageMagick.
 *
 * @param {{inputPath: string, outputPath: string, width: number|string}} body
 * @returns {Promise<string>} resolves with the output path
 */
function createThumbnail(body = {}) {
  return new Promise((resolve, reject) => {
    let inputPath, outputPath, width;

    try {
      inputPath = safeResolve(UPLOAD_DIR, body.inputPath);
      outputPath = safeResolve(THUMB_DIR, body.outputPath);

      // Width must be a plain positive integer within sane bounds:
      // this prevents things like "100 -write /etc/cron.d/x" being smuggled in.
      width = Number(body.width);
      if (!Number.isInteger(width) || width < 1 || width > 5000) {
        throw new Error('width must be an integer between 1 and 5000');
      }
    } catch (err) {
      return reject(err);
    }

    if (!fs.existsSync(inputPath)) {
      return reject(new Error('Input file not found'));
    }

    // execFile (no shell) + argument array => user input is never parsed by a shell.
    // "-" prefixes on the paths are neutralised by path.resolve making them absolute.
    const args = [
      inputPath + '[0]',        // [0] = first frame only, avoids huge multi-frame bombs
      '-auto-orient',
      '-strip',                 // drop EXIF/metadata
      '-thumbnail', `${width}x`,
      outputPath
    ];

    execFile('convert', args, { timeout: 20000, maxBuffer: 1024 * 1024 },
      (err, stdout, stderr) => {
        if (err) {
          return reject(new Error(`ImageMagick failed: ${stderr || err.message}`));
        }
        resolve(outputPath);
      });
  });
}

module.exports = { createThumbnail };
```

Notes on the security-relevant choices:

- **`execFile`, not `exec`** — no shell is spawned, so metacharacters (`;`, `` ` ``, `$()`, `|`) in the request body can't run commands.
- **Path containment** — `safeResolve` blocks `../` traversal so a client can't read `/etc/passwd` or write into a web-served/executable directory.
- **Width is validated as an integer**, not interpolated as an arbitrary string — otherwise it could inject extra ImageMagick operators such as `-write`.
- **Absolute resolved paths** prevent a filename beginning with `-` from being interpreted as a CLI flag.
- **`[0]` frame selector, `-strip`, timeout and `maxBuffer`** limit decompression-bomb and resource-exhaustion risks, and strip potentially sensitive EXIF (e.g. GPS) from user uploads.

For defence in depth, also verify the real file type (magic bytes) before conversion and consider ImageMagick's `policy.xml` to disable coders you don't need (MSL, HTTPS, EPHEMERAL, etc.).

```js
// remember-me.js
'use strict';

const crypto = require('crypto');
const cookieParser = require('cookie-parser');

const COOKIE_NAME = 'remember_me';
const MAX_AGE_MS = 30 * 24 * 60 * 60 * 1000; // 30 days

// Never put a bare user id in the cookie: it would be trivially forgeable.
// We use the "selector:validator" pattern — the selector looks the token up,
// the validator is compared against its hash in constant time.
//
// Expected persistence layer (a `remember_tokens` table):
//   db.getUserById(id)
//   db.saveRememberToken({ selector, validatorHash, userId, expiresAt })
//   db.getRememberToken(selector)          -> { selector, validatorHash, userId, expiresAt }
//   db.deleteRememberToken(selector)
//   db.deleteRememberTokensForUser(userId) // optional, for "log out everywhere"

const sha256 = (value) => crypto.createHash('sha256').update(value).digest('hex');

function cookieOptions() {
  return {
    httpOnly: true,                                 // not readable from JS
    secure: process.env.NODE_ENV === 'production',  // HTTPS only in prod
    sameSite: 'lax',                                // mitigates CSRF
    signed: true,                                   // tamper-evident
    path: '/',
    maxAge: MAX_AGE_MS,
  };
}

/**
 * Mount once, before your routes.
 * app.use(rememberMe(db, process.env.COOKIE_SECRET));
 */
function rememberMe(db, secret) {
  if (!secret) throw new Error('rememberMe: a cookie secret is required');

  const parse = cookieParser(secret);

  async function issue(res, userId) {
    const selector = crypto.randomBytes(12).toString('hex');
    const validator = crypto.randomBytes(32).toString('hex');

    await db.saveRememberToken({
      selector,
      validatorHash: sha256(validator),
      userId,
      expiresAt: new Date(Date.now() + MAX_AGE_MS),
    });

    res.cookie(COOKIE_NAME, `${selector}:${validator}`, cookieOptions());
  }

  async function clear(req, res) {
    const raw = req.signedCookies && req.signedCookies[COOKIE_NAME];
    if (raw) {
      const [selector] = String(raw).split(':');
      if (selector) await db.deleteRememberToken(selector).catch(() => {});
    }
    res.clearCookie(COOKIE_NAME, { ...cookieOptions(), maxAge: undefined });
  }

  return [
    parse,
    async function restoreUser(req, res, next) {
      // Expose helpers to route handlers.
      res.setRememberMe = (userId) => issue(res, userId);
      res.clearRememberMe = () => clear(req, res);

      // Session (if any) wins; nothing to restore.
      if (req.user) return next();

      const raw = req.signedCookies && req.signedCookies[COOKIE_NAME];
      if (!raw) return next(); // missing or bad signature -> anonymous

      const [selector, validator] = String(raw).split(':');
      if (!selector || !validator) {
        res.clearCookie(COOKIE_NAME, { ...cookieOptions(), maxAge: undefined });
        return next();
      }

      try {
        const token = await db.getRememberToken(selector);
        if (!token) {
          res.clearCookie(COOKIE_NAME, { ...cookieOptions(), maxAge: undefined });
          return next();
        }

        if (new Date(token.expiresAt).getTime() <= Date.now()) {
          await db.deleteRememberToken(selector);
          res.clearCookie(COOKIE_NAME, { ...cookieOptions(), maxAge: undefined });
          return next();
        }

        const expected = Buffer.from(token.validatorHash, 'hex');
        const actual = Buffer.from(sha256(validator), 'hex');
        const ok =
          expected.length === actual.length &&
          crypto.timingSafeEqual(expected, actual);

        if (!ok) {
          // Valid selector + wrong validator => likely a stolen/replayed cookie.
          // Invalidate every token for that user.
          if (db.deleteRememberTokensForUser) {
            await db.deleteRememberTokensForUser(token.userId);
          } else {
            await db.deleteRememberToken(selector);
          }
          res.clearCookie(COOKIE_NAME, { ...cookieOptions(), maxAge: undefined });
          return next();
        }

        const user = await db.getUserById(token.userId);
        if (!user) {
          await db.deleteRememberToken(selector);
          res.clearCookie(COOKIE_NAME, { ...cookieOptions(), maxAge: undefined });
          return next();
        }

        req.user = user;
        // Rotate on every use so a captured cookie is single-use.
        await db.deleteRememberToken(selector);
        await issue(res, user.id);

        next();
      } catch (err) {
        next(err);
      }
    },
  ];
}

module.exports = { rememberMe, COOKIE_NAME, MAX_AGE_MS };
```

