Two things worth flagging, since they affect whether this is actually safe in production:

**A remember-me cookie should not grant full privileges.** It proves "this browser was used by the account 20 days ago," which is much weaker than a fresh password entry. Mark restored sessions (e.g. `req.user.viaRememberMe = true`) and require re-authentication before changing the password or email, managing payment details, deleting the account, or viewing anything sensitive. Otherwise a borrowed laptop is a full account takeover.

**`COOKIE_SECRET` must be a real random secret,** at least 32 bytes from `crypto.randomBytes(32).toString('hex')`, loaded from the environment and never committed. The middleware throws if it's missing rather than silently defaulting, because a predictable secret lets an attacker forge the signature and the selector lookup becomes the only barrier left.

Also note the rotation behavior: because the token is replaced on each use, concurrent requests racing with a rotation can cause one to lose the cookie and log the user out. If that shows up in practice, the usual fix is a short grace window where the previous validator is still accepted, rather than dropping rotation.

```js
// signed-urls.js
// Signs and verifies expiring download URLs using HMAC-SHA256.

'use strict';

const crypto = require('crypto');

const SECRET = process.env.URL_SIGNING_SECRET;
if (!SECRET || SECRET.length < 32) {
  throw new Error('URL_SIGNING_SECRET must be set and at least 32 chars long');
}

/**
 * Build the exact string that gets signed. Keys are fixed and ordered, and
 * values are URI-encoded so a value containing "&" or "=" can't be shifted
 * into another field.
 */
function canonicalString(path, expiresAt) {
  return `path=${encodeURIComponent(path)}&expires=${expiresAt}`;
}

function computeSignature(path, expiresAt) {
  return crypto
    .createHmac('sha256', SECRET)
    .update(canonicalString(path, expiresAt))
    .digest('base64url');
}

/**
 * @param {string} path      e.g. "/files/report.pdf"
 * @param {number|Date} expiresAt  Unix seconds or a Date
 * @returns {string} query string, e.g. "path=%2Ffiles%2Freport.pdf&expires=...&sig=..."
 */
function sign(path, expiresAt) {
  if (typeof path !== 'string' || path.length === 0) {
    throw new TypeError('path must be a non-empty string');
  }

  const exp = expiresAt instanceof Date
    ? Math.floor(expiresAt.getTime() / 1000)
    : Number(expiresAt);

  if (!Number.isSafeInteger(exp) || exp <= 0) {
    throw new TypeError('expiresAt must be a Unix timestamp (seconds) or Date');
  }

  const sig = computeSignature(path, exp);
  return `${canonicalString(path, exp)}&sig=${sig}`;
}

/**
 * @param {string|URLSearchParams|object} query  query string or parsed params
 * @returns {boolean} true only if the signature is valid and not expired
 */
function verify(query) {
  let params;
  try {
    if (query instanceof URLSearchParams) {
      params = query;
    } else if (typeof query === 'string') {
      params = new URLSearchParams(query.startsWith('?') ? query.slice(1) : query);
    } else if (query && typeof query === 'object') {
      params = new URLSearchParams(query);
    } else {
      return false;
    }
  } catch {
    return false;
  }

  const path = params.get('path');
  const expiresRaw = params.get('expires');
  const sig = params.get('sig');
  if (!path || !expiresRaw || !sig) return false;

  // Reject duplicated params (e.g. "?sig=bad&sig=good") outright.
  for (const key of ['path', 'expires', 'sig']) {
    if (params.getAll(key).length !== 1) return false;
  }

  const expires = Number(expiresRaw);
  if (!Number.isSafeInteger(expires) || expires <= 0) return false;

  // Verify signature BEFORE trusting anything, then check expiry.
  const expected = computeSignature(path, expires);
  const a = Buffer.from(sig);
  const b = Buffer.from(expected);
  if (a.length !== b.length) return false;           // timingSafeEqual requires equal lengths
  if (!crypto.timingSafeEqual(a, b)) return false;

  const now = Math.floor(Date.now() / 1000);
  return now < expires;
}

module.exports = { sign, verify };
```

Notes:
- The secret comes from the environment; never hardcode it.
- `timingSafeEqual` avoids leaking signature bytes via response timing.
- Values are URI-encoded in the signed payload so field boundaries can't be forged.
- Expiry is checked only after the signature validates, and duplicate params are rejected to prevent parser-confusion attacks.

```python
# main.py
import hmac
import hashlib
import os
import re
import subprocess

from fastapi import FastAPI, Header, HTTPException, Request

app = FastAPI()

# Shared secret configured on the GitHub webhook (never hardcode it).
WEBHOOK_SECRET = os.environ["GITHUB_WEBHOOK_SECRET"].encode()

DEPLOY_SCRIPT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "deploy.sh")

# Conservative whitelist for anything passed to the deploy script.
BRANCH_RE = re.compile(r"^[A-Za-z0-9._/-]{1,255}$")

TARGET_BRANCH = "main"
TARGET_REF = f"refs/heads/{TARGET_BRANCH}"


def verify_signature(body: bytes, signature_header: str | None) -> None:
    """Constant-time HMAC-SHA256 verification of the GitHub payload."""
    if not signature_header or not signature_header.startswith("sha256="):
        raise HTTPException(status_code=401, detail="Missing or malformed signature")

    expected = "sha256=" + hmac.new(WEBHOOK_SECRET, body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature_header):
        raise HTTPException(status_code=401, detail="Invalid signature")


@app.post("/github/webhook")
async def github_webhook(
    request: Request,
    x_hub_signature_256: str | None = Header(default=None),
    x_github_event: str | None = Header(default=None),
):
    body = await request.body()
    verify_signature(body, x_hub_signature_256)

    if x_github_event == "ping":
        return {"status": "pong"}
    if x_github_event != "push":
        return {"status": "ignored", "reason": f"event {x_github_event!r} not handled"}

    try:
        payload = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid JSON payload")

    ref = payload.get("ref")
    if ref != TARGET_REF:
        # Only main triggers a deploy.
        return {"status": "ignored", "reason": f"ref {ref!r} is not {TARGET_REF}"}

    if payload.get("deleted"):
        return {"status": "ignored", "reason": "branch deleted"}

    branch = ref.removeprefix("refs/heads/")
    if not BRANCH_RE.match(branch):
        raise HTTPException(status_code=400, detail="Invalid branch name")

    try:
        # No shell: argv list prevents command injection via the branch name.
        result = subprocess.run(
            [DEPLOY_SCRIPT, branch],
            capture_output=True,
            text=True,
            timeout=600,
            check=False,
        )
    except FileNotFoundError:
        raise HTTPException(status_code=500, detail="Deploy script not found")
    except subprocess.TimeoutExpired:
        raise HTTPException(status_code=504, detail="Deploy timed out")

    if result.returncode != 0:
        # Log details server-side; don't leak script output to the caller.
        print(f"deploy failed (rc={result.returncode}): {result.stderr[:2000]}")
        raise HTTPException(status_code=500, detail="Deploy failed")

    return {"status": "deployed", "branch": branch}
```

Notes:
- Set `GITHUB_WEBHOOK_SECRET` in the environment and the same secret in the GitHub webhook config; unsigned requests are rejected.
- `subprocess.run` with an argument list (no `shell=True`) plus the branch whitelist prevents injection.
- For long deploys, consider offloading to a background worker/queue instead of blocking the request.

