        UPLOAD_ERR_INI_SIZE   => 'File exceeds the server size limit.',
        UPLOAD_ERR_FORM_SIZE  => 'File exceeds the form size limit.',
        UPLOAD_ERR_PARTIAL    => 'File was only partially uploaded.',
        UPLOAD_ERR_NO_FILE    => 'No file was selected.',
        UPLOAD_ERR_NO_TMP_DIR => 'Missing temporary folder.',
        UPLOAD_ERR_CANT_WRITE => 'Failed to write file to disk.',
        UPLOAD_ERR_EXTENSION  => 'Upload stopped by a PHP extension.',
    ];
    fail($errors[$file['error']] ?? 'Unknown upload error.');
}

// 2. Make sure it really came through an HTTP upload
if (!is_uploaded_file($file['tmp_name'])) {
    fail('Invalid upload.');
}

// 3. Size check
if ($file['size'] <= 0 || $file['size'] > MAX_BYTES) {
    fail('File must be between 1 byte and ' . (MAX_BYTES / 1024 / 1024) . ' MB.');
}

// 4. Real content-type check
$finfo = new finfo(FILEINFO_MIME_TYPE);
$mime  = $finfo->file($file['tmp_name']) ?: '';
if (!isset(ALLOWED[$mime])) {
    fail('Only JPEG, PNG, GIF or WebP images are allowed.');
}

// 5. Extra sanity check: must be a decodable image
