if ($info === false) {
    fail('File is not a valid image.');
}

// 6. Prepare destination directory (+ harden it)
if (!is_dir(UPLOAD_DIR) && !mkdir(UPLOAD_DIR, 0755, true) && !is_dir(UPLOAD_DIR)) {
    fail('Could not create upload directory.', 500);
}
$htaccess = UPLOAD_DIR . '/.htaccess';
if (!file_exists($htaccess)) {
    // Apache: never execute anything in uploads/
    file_put_contents($htaccess, "php_flag engine off\nSetHandler none\nOptions -ExecCGI -Indexes\n");
}

// 7. Random, safe filename
$ext      = ALLOWED[$mime];
$filename = bin2hex(random_bytes(16)) . '.' . $ext;
$target   = UPLOAD_DIR . '/' . $filename;

if (!move_uploaded_file($file['tmp_name'], $target)) {
    fail('Could not save the uploaded file.', 500);
}
chmod($target, 0644);

// 8. Build the public URL
$scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
$host   = $_SERVER['HTTP_HOST'] ?? 'localhost';
$url    = $scheme . '://' . $host . UPLOAD_URL_PATH . '/' . $filename;

header('Content-Type: text/html; charset=utf-8');
echo 'Uploaded: <a href="' . htmlspecialchars($url, ENT_QUOTES) . '">'
