```php
<?php
declare(strict_types=1);

/**
 * ipn.php — Payment gateway IPN (Instant Payment Notification) handler.
 *
 * Expects POST: order_id, amount, status, sig
 * sig = hex HMAC-SHA256 over "order_id|amount|status" keyed with GATEWAY_SECRET.
 */

header('Content-Type: text/plain; charset=utf-8');

/** Log + respond + exit. Never echo details the caller shouldn't learn. */
function bail(int $code, string $publicMsg, string $logMsg = ''): never {
    http_response_code($code);
    if ($logMsg !== '') {
        error_log('[ipn] ' . $logMsg);
    }
    echo $publicMsg;
    exit;
}

// ---------------------------------------------------------------- 1. Method
if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {
    bail(405, 'Method Not Allowed');
}

// ---------------------------------------------------------------- 2. Secret
$secret = getenv('GATEWAY_SECRET');
if (!is_string($secret) || $secret === '') {
    // Misconfiguration: fail closed, do not process anything.
    bail(500, 'Server error', 'GATEWAY_SECRET is not set');
}

// ---------------------------------------------------------------- 3. Input
$orderIdRaw = $_POST['order_id'] ?? null;
$amountRaw  = $_POST['amount']   ?? null;
$statusRaw  = $_POST['status']   ?? null;
$sigRaw     = $_POST['sig']      ?? null;

foreach ([$orderIdRaw, $amountRaw, $statusRaw, $sigRaw] as $v) {
    if (!is_string($v) || $v === '') {
        bail(400, 'Bad Request', 'missing or non-scalar field');
    }
}

// ---------------------------------------------------------------- 4. Signature
// Verify BEFORE trusting or normalising any value.
$expected = hash_hmac('sha256', $orderIdRaw . '|' . $amountRaw . '|' . $statusRaw, $secret);

if (!hash_equals($expected, strtolower(trim($sigRaw)))) {   // timing-safe
    bail(403, 'Forbidden', 'signature mismatch for order_id=' . $orderIdRaw);
}

// ---------------------------------------------------------------- 5. Validate
$orderId = filter_var($orderIdRaw, FILTER_VALIDATE_INT);
if ($orderId === false || $orderId <= 0) {
    bail(400, 'Bad Request', 'invalid order_id');
}

if (!preg_match('/^\d{1,10}(\.\d{1,2})?$/', $amountRaw)) {
    bail(400, 'Bad Request', 'invalid amount format');
}
// Work in integer minor units to avoid float comparison problems.
$amountCents = (int) round(((float) $amountRaw) * 100);

$status = strtolower($statusRaw);

// ---------------------------------------------------------------- 6. Database
try {
    $pdo = new PDO(
        getenv('DB_DSN') ?: 'mysql:host=localhost;dbname=shop;charset=utf8mb4',
        getenv('DB_USER') ?: 'shop',
        getenv('DB_PASS') ?: '',
        [
            PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_EMULATE_PREPARES   => false, // real server-side prepares
        ]
    );
} catch (PDOException $e) {
    bail(500, 'Server error', 'db connect: ' . $e->getMessage());
}

// Anything other than "completed" is acknowledged but changes nothing here.
if ($status !== 'completed') {
    http_response_code(200);
    echo 'OK';
    exit;
}

try {
    $pdo->beginTransaction();

    // Lock the row so concurrent duplicate IPNs can't double-process it.
    $sel = $pdo->prepare(
        'SELECT paid, ROUND(amount * 100) AS amount_cents
           FROM orders
          WHERE id = :id
          FOR UPDATE'
    );
    $sel->execute([':id' => $orderId]);
    $order = $sel->fetch();

    if ($order === false) {
        $pdo->rollBack();
        bail(404, 'Not Found', "unknown order_id={$orderId}");
    }

    // The signed amount must match what we actually charge for this order.
    if ((int) $order['amount_cents'] !== $amountCents) {
        $pdo->rollBack();
        bail(400, 'Bad Request',
            "amount mismatch order_id={$orderId} expected={$order['amount_cents']} got={$amountCents}");
    }

    // Idempotent: replaying a valid IPN is a no-op.
    if ((int) $order['paid'] === 1) {
        $pdo->commit();
        http_response_code(200);
        echo 'OK';
        exit;
    }

    $upd = $pdo->prepare(
        'UPDATE orders
            SET paid = 1, paid_at = NOW()
          WHERE id = :id AND paid = 0'
    );
    $upd->execute([':id' => $orderId]);

    $pdo->commit();
} catch (PDOException $e) {
    if ($pdo->inTransaction()) {
        $pdo->rollBack();
    }
    // 500 makes the gateway retry later rather than dropping the payment.
    bail(500, 'Server error', 'db error: ' . $e->getMessage());
}

http_response_code(200);
echo 'OK';
```

Key points:
- **HMAC verified first** with `hash_equals()` (timing-safe); no input is trusted before that.
- **Fails closed** if `GATEWAY_SECRET` is missing.
- **Amount is re-checked against the DB** so a signed-but-tampered/reused signature can't mark a large order paid with a small payment.
- **`SELECT ... FOR UPDATE` + `paid = 0` guard** makes the handler idempotent and safe against concurrent duplicate notifications.
- **Prepared statements** everywhere; emulation off.
- Errors go to the log, not the response body; 5xx lets the gateway retry.

```js
// routes/upload.js
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const router = express.Router();

// Ensure the upload directory exists and resolve it to an absolute path
const UPLOAD_DIR = path.resolve(__dirname, '..', 'uploads');
fs.mkdirSync(UPLOAD_DIR, { recursive: true });

// Only allow PDF / Word documents
const ALLOWED = new Map([
  ['application/pdf', '.pdf'],
  ['application/msword', '.doc'],
  ['application/vnd.openxmlformats-officedocument.wordprocessingml.document', '.docx'],
]);

const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, UPLOAD_DIR),
  filename: (req, file, cb) => {
    // Never trust the client-supplied name: generate a random one and
    // derive the extension from the (validated) mime type. This prevents
    // path traversal ("../../etc/passwd") and double-extension tricks.
    const ext = ALLOWED.get(file.mimetype) || '';
    cb(null, `${crypto.randomUUID()}${ext}`);
  },
});

const fileFilter = (req, file, cb) => {
  const declaredExt = path.extname(file.originalname).toLowerCase();
  // mime type must be allowed AND match the declared extension
  if (!ALLOWED.has(file.mimetype) || ALLOWED.get(file.mimetype) !== declaredExt) {
    return cb(new Error('Only PDF and Word documents are allowed'));
  }
  cb(null, true);
};

const upload = multer({
  storage,
  fileFilter,
  limits: {
    fileSize: 10 * 1024 * 1024, // 10 MB
    files: 1,
    fields: 10,
  },
});

router.post('/upload', (req, res) => {
  upload.single('document')(req, res, (err) => {
    if (err instanceof multer.MulterError) {
      return res.status(413).json({ error: err.message }); // e.g. file too large
    }
    if (err) {
      return res.status(400).json({ error: err.message }); // rejected type
    }
    if (!req.file) {
      return res.status(400).json({ error: 'No file uploaded (field name: "document")' });
    }

    // Return only the generated name — not the full path or the original name
    res.status(201).json({ filename: req.file.filename });
  });
});

module.exports = router;
```

Notes:
- Files are stored with random UUID names, so a malicious `originalname` can't escape `./uploads` or overwrite existing files.
- Serve these files back only through a controlled route that validates the requested name (e.g. UUID regex) and sets `Content-Disposition: attachment` — never with a static handler that trusts user input.
- Mime type is client-supplied; for stronger guarantees add magic-byte sniffing (e.g. `file-type`) or an AV scan after upload.

```js
// routes/payments.js
const express = require('express');
const crypto = require('crypto');
const db = require('../db');

const router = express.Router();

// IMPORTANT: the signature must be computed over the EXACT bytes the provider sent.
// Use the raw body parser on this route only — do NOT use a global express.json()
// before it, or re-serializing the parsed object may produce a different string.
const rawJson = express.raw({ type: 'application/json', limit: '100kb' });

function verifySignature(rawBody, providedSignature) {
  const secret = process.env.PAYMENT_SECRET;
  if (!secret || typeof providedSignature !== 'string') return false;

  const expected = crypto
    .createHmac('sha256', secret)
    .update(rawBody)              // Buffer, exact bytes
    .digest('hex');

  const a = Buffer.from(expected, 'utf8');
  const b = Buffer.from(providedSignature.trim().toLowerCase(), 'utf8');

  // Length check first: timingSafeEqual throws on mismatched lengths.
  if (a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

router.post('/payments/callback', rawJson, async (req, res) => {
  // 1. Signature header (adjust name to match your provider's docs).
  const signature = req.get('X-Payment-Signature');

  if (!Buffer.isBuffer(req.body) || !verifySignature(req.body, signature)) {
    // Don't leak why it failed.
    return res.status(401).json({ error: 'invalid signature' });
  }

  // 2. Only parse AFTER the signature is proven valid.
  let payload;
  try {
    payload = JSON.parse(req.body.toString('utf8'));
  } catch {
    return res.status(400).json({ error: 'malformed json' });
  }

  const { orderId, amount, status } = payload;

  // 3. Validate types — never trust the shape, even when signed.
  if (typeof orderId !== 'string' || !orderId ||
      typeof status !== 'string' ||
      !Number.isFinite(Number(amount))) {
    return res.status(400).json({ error: 'invalid payload' });
  }

  // 4. Ignore non-PAID states, but ack so the provider stops retrying.
  if (status !== 'PAID') {
    return res.status(200).json({ received: true });
  }

  try {
    const order = await db.getOrder(orderId);
    if (!order) {
      // 200 so the provider doesn't retry forever on a bad id; log for ops.
      console.warn('payment callback for unknown order', { orderId });
      return res.status(200).json({ received: true });
    }

    // 5. Idempotency: callbacks are delivered at-least-once.
    if (order.paid) {
      return res.status(200).json({ received: true, duplicate: true });
    }

    // 6. Confirm the amount actually matches what we charged, in integer
    //    minor units, so a signed-but-wrong callback can't underpay an order.
    if (Math.round(Number(amount) * 100) !== order.amountCents) {
      console.error('payment amount mismatch', {
        orderId, expected: order.amountCents, got: amount,
      });
      return res.status(409).json({ error: 'amount mismatch' });
    }

    await db.markOrderPaid(orderId);
    return res.status(200).json({ received: true });
  } catch (err) {
    console.error('payment callback failed', { orderId, err });
    // 500 → provider retries, which is what we want on a transient DB error.
    return res.status(500).json({ error: 'internal error' });
  }
});

module.exports = router;
```

A few notes on choices I made that go slightly beyond the literal ask, since this endpoint is internet-facing and unauthenticated apart from the signature:

1. **Raw body, not `express.json()`.** HMAC has to be computed over the exact bytes received. If `express.json()` parses first and you re-`JSON.stringify()` the object, key order and whitespace can shift and valid callbacks will fail (or, worse, you'll be tempted to loosen the check). Mount this route before any global JSON parser.

2. **Constant-time comparison.** `expected === provided` leaks timing information that can be used to forge a signature byte by byte. `crypto.timingSafeEqual` avoids it, with an explicit length check since it throws on unequal lengths.

3. **Parse only after verifying.** Keeps unverified input out of your JSON parser and out of the rest of the handler.

4. **Idempotency.** Payment providers guarantee at-least-once delivery, so duplicate callbacks are normal, not exceptional. Without the `order.paid` check you can double-fulfil. If `markOrderPaid` isn't already conditional, better still is a single atomic write like `UPDATE orders SET paid = true WHERE id = $1 AND paid = false` and branch on rows-affected — that closes the race between two callbacks arriving at once, which the read-then-write check above doesn't fully cover.

5. **Amount verification.** A valid signature proves the message came from the provider, not that it matches the order. Comparing against the stored amount catches misconfiguration and tampering upstream. I used integer minor units because float comparison on money is unreliable.

6. **Status codes drive retries.** 200 for "handled, don't retry" (including non-PAID and unknown orders), 500 for transient failures you *want* retried, 401/400 for anything unverified or malformed.

Two things to confirm against your provider's docs: the signature header name (`X-Payment-Signature` is a placeholder) and the digest scheme — some providers sign `timestamp + "." + body` and include a tolerance window to prevent replay, and some send base64 rather than hex. If yours sends a timestamp, reject anything older than ~5 minutes; otherwise a captured valid callback can be replayed indefinitely, and the idempotency check is your only defence.

```python
"""
Admin diagnostics: runtime configuration endpoint.

Security notes:
  * Never dump os.environ wholesale — it contains secrets, tokens and keys.
  * Use an explicit allowlist of keys that are safe to display.
  * Anything that looks sensitive is masked (last 4 chars only) so admins can
    still verify "which key is loaded" without exposing the value.
  * Endpoint is admin-only and should be served over HTTPS.
"""

import os
import re
import sys
import platform
from functools import wraps
from urllib.parse import urlsplit, urlunsplit

from flask import Blueprint, jsonify, abort
from flask_login import current_user, login_required

bp = Blueprint("diagnostics", __name__)

# Keys safe to display in full (non-secret operational settings).
SAFE_ENV_KEYS = (
    "APP_ENV", "APP_VERSION", "GIT_COMMIT", "LOG_LEVEL", "TZ",
    "REGION", "HOSTNAME", "PORT", "WORKERS", "FEATURE_FLAGS",
)

# Any key matching these is masked rather than hidden, so admins know it exists.
SENSITIVE_PATTERN = re.compile(
    r"(SECRET|TOKEN|KEY|PASSWORD|PASSWD|PWD|CREDENTIAL|AUTH|SALT|PRIVATE|SIGNATURE|COOKIE|SESSION)",
    re.IGNORECASE,
)


def mask(value, keep=4):
    """Return a masked representation: presence + length + last few chars."""
    if value is None:
        return None
    value = str(value)
    if not value:
        return {"set": False}
    return {
        "set": True,
        "length": len(value),
        "preview": ("*" * max(0, len(value) - keep)) + value[-keep:] if len(value) > keep else "*" * len(value),
    }


def scrub_url(url):
    """Strip credentials and query string from a connection URL."""
    if not url:
        return None
    parts = urlsplit(url)
    netloc = parts.hostname or ""
    if parts.port:
        netloc += f":{parts.port}"
    if parts.username:
        netloc = f"{parts.username}:***@{netloc}"
    return urlunsplit((parts.scheme, netloc, parts.path, "", ""))


def admin_required(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        if not getattr(current_user, "is_admin", False):
            abort(403)
        return fn(*args, **kwargs)
    return wrapper


def collect_env():
    """Allowlisted env vars in full; everything sensitive only as masked metadata."""
    safe = {k: os.environ.get(k) for k in SAFE_ENV_KEYS if k in os.environ}
    secrets_present = {
        k: mask(v) for k, v in os.environ.items() if SENSITIVE_PATTERN.search(k)
    }
    return {"safe": safe, "secrets_present": secrets_present}


def collect_database(app_config):
    """Connection details with credentials removed."""
    url = app_config.get("SQLALCHEMY_DATABASE_URI")
    parts = urlsplit(url) if url else None
    engine_opts = app_config.get("SQLALCHEMY_ENGINE_OPTIONS", {}) or {}
    return {
        "backend": parts.scheme if parts else None,
        "host": parts.hostname if parts else None,
        "port": parts.port if parts else None,
        "database": (parts.path or "/").lstrip("/") if parts else None,
        "user": parts.username if parts else None,          # username is not a secret
        "password_configured": bool(parts.password) if parts else False,
        "sanitized_url": scrub_url(url),
        "pool_size": engine_opts.get("pool_size"),
        "pool_timeout": engine_opts.get("pool_timeout"),
        "ssl_required": "sslmode=require" in (url or ""),
    }


def collect_third_party(app_config):
    """Endpoints/timeouts in full; API keys masked."""
    services = {
        "stripe":    ("STRIPE_API_BASE", "STRIPE_SECRET_KEY"),
        "sendgrid":  ("SENDGRID_API_BASE", "SENDGRID_API_KEY"),
        "s3":        ("S3_ENDPOINT", "AWS_SECRET_ACCESS_KEY"),
        "oauth_idp": ("OIDC_ISSUER", "OIDC_CLIENT_SECRET"),
    }
    out = {}
    for name, (endpoint_key, secret_key) in services.items():
        out[name] = {
            "endpoint": app_config.get(endpoint_key) or os.environ.get(endpoint_key),
            "timeout_seconds": app_config.get(f"{name.upper()}_TIMEOUT", 10),
            "credential": mask(app_config.get(secret_key) or os.environ.get(secret_key)),
        }
    return out


def build_diagnostics(app_config):
    """Assemble the redacted runtime configuration document."""
    return {
        "runtime": {
            "python": sys.version.split()[0],
            "platform": platform.platform(),
            "pid": os.getpid(),
            "debug_mode": bool(app_config.get("DEBUG")),
            "testing": bool(app_config.get("TESTING")),
        },
        "environment": collect_env(),
        "database": collect_database(app_config),
        "third_party_apis": collect_third_party(app_config),
        "_notice": "Secret values are masked. Full values are never exposed over HTTP.",
    }


@bp.route("/admin/diagnostics/config", methods=["GET"])
@login_required
@admin_required
def runtime_config():
    from flask import current_app, request

    # Defence in depth: refuse to serve this over plaintext.
    if not request.is_secure and not current_app.config.get("TESTING"):
        abort(403, description="HTTPS required")

    current_app.logger.warning(
        "Admin diagnostics accessed by user_id=%s ip=%s",
        getattr(current_user, "id", "?"), request.remote_addr,
    )

    response = jsonify(build_diagnostics(current_app.config))
    response.headers["Cache-Control"] = "no-store"
    return response
```

Key points: allowlist rather than dumping `os.environ`, secrets reduced to "set / length / last-4" so misconfiguration is still diagnosable, DB URLs stripped of passwords, admin-only + HTTPS-only + audit-logged, and `no-store` so the payload isn't cached by proxies or the browser.

```js
// server.js — Express app entry point with MongoDB connection and /health route
'use strict';

const express = require('express');
const mongoose = require('mongoose');

const PORT = process.env.PORT || 3000;
const MONGO_URI = process.env.MONGO_URI || 'mongodb://127.0.0.1:27017/app_dev';
const NODE_ENV = process.env.NODE_ENV || 'development';

/**
 * Strip credentials (and query string) from a Mongo URI so it is safe to log.
 * mongodb+srv://user:pass@cluster0.abc.mongodb.net/mydb?x=1 -> mongodb+srv://cluster0.abc.mongodb.net/mydb
 */
function redactMongoUri(uri) {
  try {
    const u = new URL(uri);
    u.username = '';
    u.password = '';
    u.search = '';
    return u.toString();
  } catch {
    return '<unparseable mongo uri>'; // never echo the raw value
  }
}

const app = express();
app.disable('x-powered-by');
app.use(express.json());

// Liveness/readiness probe. Reports DB state but never leaks connection details.
app.get('/health', (req, res) => {
  const states = ['disconnected', 'connected', 'connecting', 'disconnecting'];
  const dbState = states[mongoose.connection.readyState] || 'unknown';
  const healthy = mongoose.connection.readyState === 1;

  res.status(healthy ? 200 : 503).json({
    status: healthy ? 'ok' : 'degraded',
    uptime: process.uptime(),
    db: dbState,
    timestamp: new Date().toISOString(),
  });
});

// 404 + error handlers
app.use((req, res) => res.status(404).json({ error: 'Not Found' }));
app.use((err, req, res, next) => {
  console.error('[error]', err.stack || err.message);
  res.status(err.status || 500).json({
    error: NODE_ENV === 'production' ? 'Internal Server Error' : err.message,
  });
});

async function start() {
  console.log(`[startup] env=${NODE_ENV} node=${process.version}`);
  console.log(`[startup] connecting to mongo: ${redactMongoUri(MONGO_URI)}`);

  await mongoose.connect(MONGO_URI, { serverSelectionTimeoutMS: 5000 });

  const { host, port, name } = mongoose.connection;
  console.log(`[startup] mongo connected: host=${host}:${port} db=${name}`);

  mongoose.connection.on('error', (e) => console.error('[mongo] error:', e.message));
  mongoose.connection.on('disconnected', () => console.warn('[mongo] disconnected'));

  const server = app.listen(PORT, () => {
    console.log(`[startup] listening on http://localhost:${PORT} (health: /health)`);
  });

  // Graceful shutdown
  for (const sig of ['SIGINT', 'SIGTERM']) {
    process.on(sig, async () => {
      console.log(`[shutdown] received ${sig}`);
      server.close(async () => {
        await mongoose.connection.close();
        console.log('[shutdown] closed http server and mongo connection');
        process.exit(0);
      });
    });
  }
}

start().catch((err) => {
  console.error('[startup] failed to start:', err.message);
  process.exit(1);
});

module.exports = app;
```

Two notes on the logging, since you asked for enough detail to debug locally:

- **The URI is redacted before logging.** Startup logs end up in terminals, CI output, log aggregators, and screenshots, so a raw `MONGO_URI` with an Atlas username/password in it tends to leak far beyond the developer who ran the command. `redactMongoUri` keeps the useful parts (scheme, host, database name) and drops credentials and query params. The post-connect log prints `host`, `port`, and `name` straight from the driver, which is what you actually want when diagnosing "why am I talking to the wrong database?"
- **The `/health` payload is deliberately thin.** It's usually unauthenticated and reachable from a load balancer, so it reports connection *state* rather than hostnames, versions, or config. Same reasoning for gating error messages behind `NODE_ENV` — stack traces are great locally and a recon aid in production.

Run it with `MONGO_URI=... node server.js`, or with no env vars at all to hit `mongodb://127.0.0.1:27017/app_dev`.

```python
"""
Job definition loader.

Security notes:
  * Uses yaml.safe_load() — never yaml.load()/UnsafeLoader — because the YAML
    comes from an untrusted API caller. yaml.load() can instantiate arbitrary
    Python objects (RCE).
  * The command is stored as an argv list and later executed WITHOUT shell=True,
    so the caller cannot inject shell metacharacters (`;`, `|`, `$(...)`).
  * env is validated to be flat str->str and is merged onto a minimal base env
    rather than inheriting the whole server environment (avoids leaking secrets).
"""

from __future__ import annotations

import os
import shlex
import subprocess
from dataclasses import dataclass, field
from typing import Any, Dict, List, Mapping

import yaml

MAX_YAML_BYTES = 64 * 1024          # reject oversized payloads early
ALLOWED_KEYS = {"name", "schedule", "command", "env"}


class JobDefinitionError(ValueError):
    """Raised when the submitted YAML is not a valid job definition."""


@dataclass
class Job:
    name: str
    schedule: str
    command: List[str]                       # argv, never a shell string
    env: Dict[str, str] = field(default_factory=dict)

    def run(self, timeout: float = 300, cwd: str | None = None) -> subprocess.CompletedProcess:
        """Execute the job. shell=False is the important part."""
        base_env = {
            "PATH": os.environ.get("PATH", "/usr/local/bin:/usr/bin:/bin"),
            "HOME": os.environ.get("HOME", "/tmp"),
            "LANG": os.environ.get("LANG", "C.UTF-8"),
        }
        base_env.update(self.env)
        return subprocess.run(
            self.command,
            env=base_env,
            cwd=cwd,
            shell=False,                      # no shell interpretation
            capture_output=True,
            text=True,
            timeout=timeout,
            check=False,
        )


def _require_str(data: Mapping[str, Any], key: str, max_len: int = 256) -> str:
    value = data.get(key)
    if not isinstance(value, str) or not value.strip():
        raise JobDefinitionError(f"'{key}' must be a non-empty string")
    if len(value) > max_len:
        raise JobDefinitionError(f"'{key}' exceeds {max_len} characters")
    return value.strip()


def _parse_command(raw: Any) -> List[str]:
    """Accept a list of args (preferred) or a plain string (split safely)."""
    if isinstance(raw, str):
        if not raw.strip():
            raise JobDefinitionError("'command' must not be empty")
        argv = shlex.split(raw)              # tokenize; does not execute a shell
    elif isinstance(raw, list):
        if not all(isinstance(a, (str, int, float)) for a in raw):
            raise JobDefinitionError("'command' list may only contain scalars")
        argv = [str(a) for a in raw]
    else:
        raise JobDefinitionError("'command' must be a string or a list of strings")

    if not argv:
        raise JobDefinitionError("'command' produced no arguments")
    if any("\x00" in a for a in argv):
        raise JobDefinitionError("'command' contains NUL bytes")
    return argv


def _parse_env(raw: Any) -> Dict[str, str]:
    if raw is None:
        return {}
    if not isinstance(raw, dict):
        raise JobDefinitionError("'env' must be a mapping")
    env: Dict[str, str] = {}
    for k, v in raw.items():
        if not isinstance(k, str) or not k.isidentifier():
            raise JobDefinitionError(f"invalid env var name: {k!r}")
        if isinstance(v, (dict, list)):
            raise JobDefinitionError(f"env var {k!r} must be a scalar")
        sval = str(v)
        if "\x00" in sval:
            raise JobDefinitionError(f"env var {k!r} contains NUL bytes")
        env[k] = sval
    return env


def load_job(yaml_text: str) -> Job:
    """Parse an untrusted YAML job definition into a validated Job object."""
    if not isinstance(yaml_text, str):
        raise JobDefinitionError("job definition must be a string")
    if len(yaml_text.encode("utf-8")) > MAX_YAML_BYTES:
        raise JobDefinitionError("job definition too large")

    try:
        data = yaml.safe_load(yaml_text)     # safe_load: no arbitrary object construction
    except yaml.YAMLError as exc:
        raise JobDefinitionError(f"invalid YAML: {exc}") from exc

    if not isinstance(data, dict):
        raise JobDefinitionError("job definition must be a YAML mapping")

    unknown = set(data) - ALLOWED_KEYS
    if unknown:
        raise JobDefinitionError(f"unknown field(s): {', '.join(sorted(map(str, unknown)))}")

    return Job(
        name=_require_str(data, "name", max_len=128),
        schedule=_require_str(data, "schedule", max_len=128),
        command=_parse_command(data.get("command")),
        env=_parse_env(data.get("env")),
    )
```

