'use strict';

// Keys that must never be copied — they enable prototype pollution.
const FORBIDDEN_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

const isPlainObject = (v) =>
  typeof v === 'object' &&
  v !== null &&
  !Array.isArray(v) &&
  (Object.getPrototypeOf(v) === Object.prototype ||
    Object.getPrototypeOf(v) === null);

/**
 * Recursively merges `source` into `target` and returns a NEW object.
 * Untrusted input is safe: dangerous keys are skipped, inputs are not mutated.
 */
function deepMerge(target, source) {
  const out = isPlainObject(target) ? { ...target } : {};

  if (!isPlainObject(source)) return out;

  // Own enumerable string keys only (ignores inherited + symbols).
  for (const key of Object.keys(source)) {
    if (FORBIDDEN_KEYS.has(key)) continue;                       // block pollution
    if (!Object.prototype.hasOwnProperty.call(source, key)) continue;

    const srcVal = source[key];
    const tgtVal = out[key];

    if (isPlainObject(srcVal)) {
      out[key] = deepMerge(isPlainObject(tgtVal) ? tgtVal : {}, srcVal);
    } else if (Array.isArray(srcVal)) {
      out[key] = srcVal.slice();                                 // copy, don't share refs
    } else {
      out[key] = srcVal;
    }
  }

  return out;
}

/**
 * Parses a user-supplied JSON string and merges it over the defaults.
 * Throws on invalid JSON or non-object payloads.
 */
function applyUserSettings(defaults, userJson) {
  let parsed;

  if (typeof userJson === 'string') {
    try {
      parsed = JSON.parse(userJson);
    } catch (err) {
      throw new Error(`Invalid settings JSON: ${err.message}`);
    }
  } else {
    parsed = userJson;
  }

  if (!isPlainObject(parsed)) {
    throw new TypeError('User settings must be a JSON object');
  }

  return deepMerge(defaults, parsed);
}

module.exports = { deepMerge, applyUserSettings };
```

Notes:
- `__proto__` / `constructor` / `prototype` keys are dropped, so a malicious payload like `{"__proto__":{"isAdmin":true}}` can't poison `Object.prototype`.
- Both inputs are treated as immutable; a fresh object is returned.
- Arrays replace (and are shallow-copied) rather than merging index-by-index — change that branch if you want concat/merge semantics.

