import os
from flask import Flask, jsonify, request, make_response, abort

from auth import get_current_user  # your existing helper

app = Flask(__name__)

# Explicit allow-list of frontend origins (comma-separated env var).
ALLOWED_ORIGINS = {
    o.strip()
    for o in os.environ.get(
        "CORS_ALLOWED_ORIGINS", "https://app.example.com"
    ).split(",")
    if o.strip()
}


def _cors_headers(response):
    """Attach CORS headers when the Origin is explicitly allowed."""
    origin = request.headers.get("Origin")
    if origin and origin in ALLOWED_ORIGINS:
        response.headers["Access-Control-Allow-Origin"] = origin
        response.headers["Access-Control-Allow-Credentials"] = "true"
        response.headers["Access-Control-Allow-Methods"] = "GET, OPTIONS"
        response.headers["Access-Control-Allow-Headers"] = "Content-Type"
        response.headers["Access-Control-Max-Age"] = "600"
        # Caches must key on Origin since the header varies per requester.
        response.headers.add("Vary", "Origin")
    return response


app.after_request(_cors_headers)


@app.route("/api/profile", methods=["GET", "OPTIONS"])
def profile():
    # Preflight: headers are added by after_request.
    if request.method == "OPTIONS":
        return make_response("", 204)

    user = get_current_user()
    if user is None:
        abort(401, description="Authentication required")

    return jsonify(
        {
            "id": user.id,
            "username": user.username,
            "email": user.email,
            "display_name": getattr(user, "display_name", None),
            "created_at": user.created_at.isoformat() if user.created_at else None,
        }
    )


@app.errorhandler(401)
def unauthorized(err):
    return jsonify({"error": "unauthorized", "message": err.description}), 401


if __name__ == "__main__":
    app.run(port=5000, debug=True)
