```js
// routes/go.js
const express = require('express');
const router = express.Router();

// Allowlist of external hosts we're willing to redirect to.
// Keeping this list prevents the endpoint from becoming an open redirect
// (attackers love /go?url=https://phishing.example for credible-looking links).
const ALLOWED_HOSTS = new Set([
  'example.com',
  'www.example.com',
  'docs.partner.io',
  'blog.partner.io',
]);

function isAllowedTarget(rawUrl) {
  let parsed;
  try {
    parsed = new URL(rawUrl); // throws on relative/garbage input
  } catch {
    return null;
  }

  // Only http(s) — blocks javascript:, data:, file:, etc.
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return null;

  // Exact host match; subdomain suffix checks (endsWith) are easy to bypass
  // with things like "evil-example.com".
  if (!ALLOWED_HOSTS.has(parsed.hostname.toLowerCase())) return null;

  return parsed;
}

router.get('/go', (req, res) => {
  const { url } = req.query;

  // Missing, empty, or repeated (?url=a&url=b makes it an array) param
  if (typeof url !== 'string' || url.trim() === '') {
    return res.status(400).json({ error: 'Missing required query parameter: url' });
  }

  const target = isAllowedTarget(url.trim());
  if (!target) {
    // Don't echo the raw input back into HTML/JSON error text.
    return res.status(400).json({ error: 'Invalid or disallowed redirect target' });
  }

  // Log the outbound click. Log the normalized URL, not the raw user string.
  req.app.locals.logger?.info?.('outbound_click', {
    target: target.href,
    host: target.hostname,
    referrer: req.get('referer') || null,
    userAgent: req.get('user-agent') || null,
    userId: req.user?.id ?? null,
    at: new Date().toISOString(),
  });

  // 302: temporary, so browsers/proxies don't cache the mapping.
  res.redirect(302, target.href);
});

module.exports = router;
```

**Note on the allowlist:** a redirector that forwards to any user-supplied URL is a classic open redirect — it gets abused in phishing because the link starts with your trusted domain. If you truly need to support arbitrary destinations (e.g. user-generated content links), safer options are:

1. Store destinations server-side and redirect by opaque ID: `/go?id=abc123`.
2. Sign the URL with an HMAC you generate when rendering the link, and verify the signature before redirecting.
3. Show an interstitial "You are leaving example.com" page instead of an automatic redirect.

Option 2 looks like:

```js
const crypto = require('crypto');

const sign = (url) =>
  crypto.createHmac('sha256', process.env.REDIRECT_SECRET).update(url).digest('hex');

// GET /go?url=...&sig=...
router.get('/go', (req, res) => {
  const { url, sig } = req.query;
  if (typeof url !== 'string' || !url) {
    return res.status(400).json({ error: 'Missing required query parameter: url' });
  }
  const expected = sign(url);
  const provided = typeof sig === 'string' ? sig : '';
  // timingSafeEqual requires equal-length buffers
  const ok =
    provided.length === expected.length &&
    crypto.timingSafeEqual(Buffer.from(provided), Buffer.from(expected));
  if (!ok) return res.status(400).json({ error: 'Invalid signature' });

  // still enforce http(s) even for signed URLs
  // ... log + res.redirect(302, url)
});
```

```js
// cors.js — configurable CORS middleware with credential support
//
// Security notes:
//  - With credentials, Access-Control-Allow-Origin MUST echo a single exact
//    origin ("*" is rejected by browsers), so we validate against an allowlist.
//  - Always send `Vary: Origin` so caches/CDNs don't serve one partner's
//    ACAO header to another origin.

const DEFAULTS = {
  allowedOrigins: [],            // exact strings and/or RegExp
  allowedMethods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  exposedHeaders: [],            // headers JS on the client may read
  credentials: true,
  maxAge: 600,                   // preflight cache, seconds
};

function isAllowed(origin, allowedOrigins) {
  return allowedOrigins.some((rule) =>
    rule instanceof RegExp ? rule.test(origin) : rule === origin
  );
}

function cors(userOptions = {}) {
  const opts = { ...DEFAULTS, ...userOptions };

  return function corsMiddleware(req, res, next) {
    const origin = req.headers.origin;

    // Always vary on Origin, even when we don't set ACAO.
    res.vary('Origin');

    // Same-origin / non-browser request: nothing to do.
    if (!origin) return next();

    if (!isAllowed(origin, opts.allowedOrigins)) {
      // Unknown origin: omit CORS headers. Preflight ends here so the
      // browser blocks the real request; simple requests still hit the
      // route but the response is unreadable to the page.
      if (req.method === 'OPTIONS') return res.sendStatus(204);
      return next();
    }

    res.setHeader('Access-Control-Allow-Origin', origin);
    if (opts.credentials) {
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }
    if (opts.exposedHeaders.length) {
      res.setHeader('Access-Control-Expose-Headers', opts.exposedHeaders.join(', '));
    }

    // Preflight
    if (req.method === 'OPTIONS') {
      res.setHeader('Access-Control-Allow-Methods', opts.allowedMethods.join(', '));

      // Echo requested headers if configured to be permissive, else use allowlist.
      const requested = req.headers['access-control-request-headers'];
      res.setHeader(
        'Access-Control-Allow-Headers',
        opts.allowedHeaders.length ? opts.allowedHeaders.join(', ') : (requested || '')
      );
      res.vary('Access-Control-Request-Headers');

      res.setHeader('Access-Control-Max-Age', String(opts.maxAge));
      return res.sendStatus(204); // no body, don't run route handlers
    }

    return next();
  };
}

module.exports = cors;
```

